// Lê TODOS os scores do Redis (nó "Redis Keys" com Get Values) e monta 1 CSV consolidado,
// ranqueado dentro de cada macro tema, e devolve como arquivo binário (data) pro Google Drive.
const recs = [];
function pushParsed(v) {
  let r = v;
  if (typeof v === 'string') { try { r = JSON.parse(v); } catch (e) { return; } }
  if (r && r.id) recs.push(r);
}
for (const it of items) {
  const j = it.json || {};
  if (j.value !== undefined && (j.key || j.name)) pushParsed(j.value);       // formato {key, value}
  else for (const [k, v] of Object.entries(j)) if (k.indexOf('pcur:pal:') === 0) pushParsed(v); // {chave: valor}
}

// agrupa por macro tema
const byTema = {};
for (const r of recs) { const t = r.macro_tema || '18. OUTROS'; (byTema[t] = byTema[t] || []).push(r); }
// ordena temas pelo número do rótulo (1..25)
const temas = Object.keys(byTema).sort((a, b) => (parseInt(a) || 999) - (parseInt(b) || 999));

function esc(v) { const s = String(v == null ? '' : v); return /[",\n;]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; }
const header = ['macro_tema', 'rank', 'nome', 'pontuacao_total', 'compatibilidade_pct', 'quem_e', 'defende', 'entrega', 'pra_quem', 'comprova', 'raiox', 'hubspot_id', 'wiki_url'];
const out = [header.join(',')];
for (const t of temas) {
  const lst = byTema[t].slice().sort((a, b) => (b.pontuacao_total || 0) - (a.pontuacao_total || 0));
  lst.forEach((r, i) => {
    const n = r.notas || {};
    out.push([
      esc(t), i + 1, esc(r.nome), r.pontuacao_total, r.compatibilidade,
      n.quem_e, n.defende, n.entrega, n.pra_quem, n.comprova, n.raiox,
      r.id, esc(r.wiki_url)
    ].join(','));
  });
}
const csv = '﻿' + out.join('\r\n'); // BOM + CRLF: Excel abre com acento certo
const base64 = Buffer.from(csv, 'utf8').toString('base64');

return [{
  json: { total_avaliados: recs.length, temas: temas.length },
  binary: { data: { data: base64, mimeType: 'text/csv', fileName: 'ranking_palestrantes.csv' } }
}];
